class FindSumPairs { vector<int> nums1,nums2;unordered_map<int,int> frequency;public: FindSumPairs(vector<int>& first,vector<int>& second):nums1(first),nums2(second){for(int value:nums2)++frequency[value];}void add(int index,int value){--frequency[nums2[index]];nums2[index]+=value;++frequency[nums2[index]];}int count(int total){int answer=0;for(int value:nums1)answer+=frequency[total-value];return answer;} };
